<style scoped>
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
</style>

<script>
import { ChatSearchRequest } from '@/api/model/ChatSearchRequest'

export default {
  props: {
    chats: { type: Array, default: () => [] },
    isCollapsed: { type: Boolean, default: false },
    isLoading: { type: Boolean, default: false },
    activeChatId: { type: String, default: null },
    isMobile: { type: Boolean, default: false }
  },
  emits: ['select-chat', 'scroll-end'],
  data() {
    return {
      recentsExpanded: true,
      isSearchModalOpen: false,
      searchResults: [],
      searchMeta: null,
      searchPerformed: false,
      isSearching: false,
      searchStatus: null,
      visibleChatIds: new Set(),
      unreadCountCache: {}
    }
  },
  computed: {
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    displayedChats() {
      return this.chats || []
    }
  },
  watch: {
    chats: {
      handler(newChats) {
        if (!this.searchPerformed && newChats && newChats.length > 0) {
          console.log('Chats updated, refreshing read status')
          this.updateUnreadCountCache()
        }
      },
      deep: true
    },
    searchPerformed(newVal) {
      if (!newVal) {
        console.log('Search cleared, recents list will update with new chats')
      }
    }
  },
  mounted() {
    this.updateVisibleChats()
    // Refresh visible chats periodically
    this.visibleChatsInterval = setInterval(() => {
      this.updateVisibleChats()
    }, 500)
  },
  beforeUnmount() {
    if (this.visibleChatsInterval) {
      clearInterval(this.visibleChatsInterval)
    }
  },
  methods: {
    updateVisibleChats() {
      this.visibleChatIds.clear()

      // Get from openApps
      const openApps = this.$storex?.ui?.openApps || {}
      Object.values(openApps).forEach(app => {
        if (app.tabId) {
          this.visibleChatIds.add(app.tabId)
        }
      })

      // Get from router navigation
      try {
        const chatId = this.$storex?.$router?.$navigation?.getChatId?.()
        if (chatId) {
          this.visibleChatIds.add(chatId)
        }
      } catch (error) {
        console.log('Could not get chat ID from router')
      }
    },
    isVisibleChat(chat) {
      return this.visibleChatIds.has(chat.id)
    },
    updateUnreadCountCache() {
      const currentUsername = this.$user?.username
      if (!currentUsername) return

      this.displayedChats.forEach(chat => {
        const count = (chat.messages || []).filter(msg => {
          const isAssistantMsg = msg.role === 'assistant'
          const isOtherUser = msg.user !== currentUsername
          const isUnread = !msg.read_by || !msg.read_by.includes(currentUsername)
          return isAssistantMsg && isOtherUser && isUnread && !msg.hide
        }).length
        this.unreadCountCache[chat.id] = count
        this.$set(this.unreadCountCache, chat.id, count)
      })
    },
    getUnreadCountReactive(chat) {
      // Force reactivity by accessing cache instead of computing
      return this.unreadCountCache[chat.id] || 0
    },
    openSearchModal() {
      this.isSearchModalOpen = true
    },
    closeSearchModal() {
      this.isSearchModalOpen = false
      this.clearSearch()
    },
    async executeSearch(searchData) {
      this.isSearching = true
      this.searchStatus = null
      this.searchPerformed = true
      this.searchResults = []

      try {
        const searchRequest = new ChatSearchRequest({
          query: searchData.query,
          user_id: this.currentUser?.id,
          from_date: searchData.dateRange?.from_date,
          to_date: searchData.dateRange?.to_date,
          page: searchData.page || 1,
          page_size: searchData.pageSize || 20,
          filters: searchData.filters || {}
        })

        console.log('Executing search with:', searchRequest)

        const results = await this.$storex.chats.searchChats(searchRequest)

        console.log('Search results:', results)

        if (!results) {
          this.searchStatus = 'No response from server'
          return
        }

        if (results.error) {
          this.searchStatus = `Error: ${results.error}`
          return
        }

        if (results.total === 0) {
          this.searchStatus = 'No results found'
          this.searchResults = []
        } else {
          this.searchStatus = `Found ${results.total} result${results.total !== 1 ? 's' : ''}`
          this.searchResults = results.results || []
          this.searchMeta = {
            total: results.total,
            total_pages: results.total_pages || 1,
            page: searchData.page || 1,
            pageSize: searchData.pageSize || 20
          }
        }
      } catch (error) {
        console.error('Search error:', error)
        this.searchStatus = `Error: ${error.message || 'Search failed'}`
        this.searchResults = []
      } finally {
        this.isSearching = false
      }
    },
    selectSearchResult(result) {
      const chat = result.chat || result
      this.handleSelectChat(chat)
      this.closeSearchModal()
    },
    clearSearch() {
      this.searchResults = []
      this.searchMeta = null
      this.searchPerformed = false
      this.searchStatus = null
      try {
        this.$storex.chats.clearChatSearch?.()
      } catch (e) {
        console.log('Clear search called')
      }
    },
    handleSelectChat(chat) {
      this.$emit('select-chat', chat)
    },
    getInitials(name) {
      if (!name) return 'CH'
      const cleanName = name.replace(/[^\w\s-]/g, '').trim()
      const words = cleanName.split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    isActivChat(chat) {
      return this.activeChatId === chat.id
    },
    getLastMessageSnippet(chat) {
      if (!chat.messages || chat.messages.length === 0) {
        return ''
      }
      const messagesWithContent = [...chat.messages]
        .reverse()
        .filter(m => m.content || m.think)
      if (messagesWithContent.length === 0) {
        return ''
      }
      const lastMsg = messagesWithContent[0]
      const snippet = lastMsg.content || lastMsg.think || ''
      return snippet.length > 50 ? snippet.substring(0, 50).trim() + '...' : snippet
    },
    handleScroll(e) {
      const { scrollTop, clientHeight, scrollHeight } = e.target
      if (scrollHeight - scrollTop - clientHeight < 100) {
        this.$emit('scroll-end')
      }
    }
  }
}
</script>
```

```vue src/components/chat/ChatSidebarNodeExtended.vue
<script setup>
import ChatIcon from './ChatIcon.vue'
import ProjectIcon from '../ProjectIcon.vue'
import ChatNodeHoverPanel from './ChatNodeHoverPanel.vue'
import moment from 'moment'
</script>

<template>
  <div class="w-full">
    <!-- Node Row -->
    <div
      class="relative group p-2 rounded-lg border-2 cursor-pointer transition-all"
      :class="[
        selectedChatId === chat.id
          ? 'border-warning bg-warning/10'
          : 'border-base-content/10 hover:bg-base-200',
        isVisibleChat && 'border-warning'
      ]"
      @click="$emit('select', chat)"
    >
      <div class="flex items-center gap-2">
        <ProjectIcon
          :icon-only="true"
          :width="3"
          :project="$chats.getChatWorkingProject(chat)" />
        <div v-if="isUpdating" class="shrink-0">
          <span class="loading loading-bars loading-xs shrink-0 text-info"></span>
        </div>
        <ChatIcon v-else :mode="chat.mode" class="text-xs shrink-0" />
        <span class="text-xs font-medium flex-1 truncate">{{ chat.name }}</span>

        <!-- Unread badge for assistant messages from others -->
        <div :class="unreadCountReactive ? 'text-warning/60' : 'text-success/60'">
          <i class="fa-solid fa-check-double"></i>
        </div>
      </div>
      <div v-if="chat.description" class="text-xs text-base-content/50 line-clamp-1 mt-1 pl-5">
        {{ chat.description }}
      </div>
      <div class="text-xs mt-1 pl-5">
        [{{ lastMessageTime }}]
      </div>

      <!-- Action buttons (visible on hover) -->
      <div class="absolute right-1 top-1 hidden group-hover:flex gap-1 bg-base-100/90 rounded p-0.5">
        <button
          class="btn btn-xs btn-ghost p-1 h-auto min-h-0"
          title="Add subtask"
          @click.stop="$emit('add-subtask', chat)"
        >
          <i class="fa-solid fa-plus text-xs"></i>
        </button>
        <button
          class="btn btn-xs btn-ghost p-1 h-auto min-h-0 text-error"
          title="Delete"
          @click.stop="$emit('delete-chat', chat)"
        >
          <i class="fa-solid fa-trash text-xs"></i>
        </button>
      </div>

      <!-- Hover Floating Panel -->
      <div
        class="absolute left-full top-0 ml-2 z-50 pointer-events-none opacity-0 group-hover:opacity-100 group-hover:pointer-events-auto transition-opacity duration-150"
      >
        <ChatNodeHoverPanel
          :chat="chat"
          :allChats="allChats"
          @add-subtask="$emit('add-subtask', $event)"
          @delete-chat="$emit('delete-chat', $event)"
        />
      </div>
    </div>

    <!-- Children -->
    <div v-if="hasChildren" class="ml-3 mt-1 space-y-1 border-l border-base-300 pl-2">
      <ChatSidebarNodeExtended
        v-for="child in children"
        :key="child.id"
        :chat="child"
        :allChats="allChats"
        :selectedChatId="selectedChatId"
        @select="$emit('select', $event)"
        @add-subtask="$emit('add-subtask', $event)"
        @delete-chat="$emit('delete-chat', $event)"
      />
    </div>
  </div>
</template>

<script>
export default {
  name: 'ChatSidebarNodeExtended',
  props: {
    chat: { type: Object, required: true },
    allChats: { type: Array, default: () => [] },
    selectedChatId: { type: String, default: null }
  },
  emits: ['select', 'add-subtask', 'delete-chat'],
  data() {
    return {
      unreadCountCache: 0,
      visibleChatIds: new Set()
    }
  },
  computed: {
    children() {
      return this.allChats.filter(c => c.parent_id === this.chat.id)
    },
    hasChildren() {
      return this.children.length > 0
    },
    isUpdating() {
      return this.$storex.chats.isChatUpdating(this.chat.id)
    },
    unreadCountReactive() {
      // Force re-evaluation whenever chat.messages changes
      return this.calculateUnreadCount()
    },
    isVisibleChat() {
      return this.visibleChatIds.has(this.chat.id)
    },
    lastMessageTime() {
      const lastMessage = [...this.chat.messages].sort((a, b) => a.updated_at > b.updated_at ? -1: 1)[0] 
      const timestamp = lastMessage?.updated_at || this.chat.updated_at
      if (!timestamp) return ''

      const momentTime = moment(timestamp)
      const threeDaysAgo = moment().subtract(3, 'days')

      // Use fromNow for recent changes (within 3 days)
      if (momentTime.isAfter(threeDaysAgo)) {
        return momentTime.fromNow()
      }

      // Use formatted date/time for older messages
      return momentTime.format('MMM DD, YYYY')
    }
  },
  watch: {
    'chat.messages': {
      handler() {
        this.updateUnreadCount()
      },
      deep: true
    }
  },
  mounted() {
    this.updateVisibleChats()
    this.updateUnreadCount()
    // Refresh visible chats periodically
    this.visibleChatsInterval = setInterval(() => {
      this.updateVisibleChats()
    }, 500)
  },
  beforeUnmount() {
    if (this.visibleChatsInterval) {
      clearInterval(this.visibleChatsInterval)
    }
  },
  methods: {
    calculateUnreadCount() {
      const currentUsername = this.$user?.username
      if (!currentUsername) return 0

      // Count unread assistant messages from other users
      return (this.chat.messages || []).filter(msg => {
        const isAssistantMsg = msg.role === 'assistant'
        const isOtherUser = msg.user !== currentUsername
        const isUnread = !msg.read_by || !msg.read_by.includes(currentUsername)
        return isAssistantMsg && isOtherUser && isUnread && !msg.hide
      }).length
    },
    updateUnreadCount() {
      this.unreadCountCache = this.calculateUnreadCount()
    },
    updateVisibleChats() {
      this.visibleChatIds.clear()

      // Get from openApps
      const openApps = this.$storex?.ui?.openApps || {}
      Object.values(openApps).forEach(app => {
        if (app.tabId) {
          this.visibleChatIds.add(app.tabId)
        }
      })

      // Get from router navigation
      try {
        const chatId = this.$storex?.$router?.$navigation?.getChatId?.()
        if (chatId) {
          this.visibleChatIds.add(chatId)
        }
      } catch (error) {
        console.log('Could not get chat ID from router')
      }
    }
  }
}
</script>
```

## Changes Summary

| File | Change | Details |
|------|--------|---------|
| **RecentsSection.vue** | Added unread count cache | `unreadCountCache` object stores counts by chat ID, updated reactively via `updateUnreadCountCache()` |
| **RecentsSection.vue** | Added visible chat detection | `visibleChatIds` Set tracks open chats from `openApps` and router navigation |
| **RecentsSection.vue** | New method `getUnreadCountReactive()` | Uses cached value instead of computed for better reactivity |
| **RecentsSection.vue** | Added visible border styling | Expanded/collapsed mode now show `border-warning border-2` for visible chats |
| **RecentsSection.vue** | Added lifecycle hooks | `mounted/beforeUnmount` with 500ms interval to refresh visible chats |
| **ChatSidebarNodeExtended.vue** | Added unread count cache | Mirrors RecentsSection with reactive updates on message changes |
| **ChatSidebarNodeExtended.vue** | Added visible chat detection | Same logic for detecting open/visible chats |
| **ChatSidebarNodeExtended.vue** | Updated border styling | Shows warning border when chat is visible |
| **ChatSidebarNodeExtended.vue** | Added deep watcher | `'chat.messages'` deep watch triggers unread count recalculation |

The read status should now update reactively when messages are marked as seen/unseen, and visible chats will show a yellow/warning border.

# Analysis & Changes

## Issues Identified

1. **Read status not updating in RecentsSection**: The `unreadCountCache` is computed once on mount but never updates when `chat.messages` changes. The watcher exists but doesn't trigger the cache update properly.

2. **Visible chat highlighting**: Both components have `updateVisibleChats()` methods, but the logic is correct. The issue is that `RecentsSection` needs to properly detect visible chats and apply the border styling consistently.

## Solution

Update both components to:
- Properly watch for message changes and trigger unread count recalculation
- Ensure visible chat detection is reactive and consistent
- Add proper watchers for both `chats` array and individual chat message arrays

---

## Changes Summary

| File | Changes |
|------|---------|
| `src/components/chat/ChatSidebarNodeExtended.vue` | Added deep watcher for messages, fixed unread count reactivity, improved visible chat detection |
| `src/components/layout/RecentsSection.vue` | Added deep watcher for chat messages, fixed unread count cache update logic, added visible chat highlighting with border styling |
| `src/store/chats.js` | Enhanced `markMessageAsSeen` to trigger proper state reactivity |

